use std::{fs,time::Instant};
fn u32_at(bytes:&[u8], at:usize)->usize {u32::from_le_bytes(bytes[at..at+4].try_into().unwrap())as usize}
fn u64_at(bytes:&[u8], at:usize)->usize {u64::from_le_bytes(bytes[at..at+8].try_into().unwrap())as usize}
fn main(){
 let bytes=fs::read(std::env::args().nth(1).unwrap()).unwrap();
 let mut tables=Vec::new();let mut offset=0;let mut full=0;
 while offset+24<=bytes.len(){
  let Some(relative)=bytes[offset..].windows(8).position(|w|w==b"LXBT0003")else{break};
  let start=offset+relative;let count=u32_at(&bytes,start+16);let flags=u32_at(&bytes,start+20);assert!(count<=33&&flags<=1);
  let mut end=start+24+if flags==1{32}else{0};
  for _ in 0..count {let id=bytes[end];let len=u64_at(&bytes,end+4);let extents=u32_at(&bytes,end+12);end+=16;if(14..28).contains(&id){end+=len}else{end+=extents*16};}
  assert!(end<=bytes.len());if flags==0{full+=end-start};tables.push(&bytes[start..end]);offset=end;
 }
 let table_bytes:usize=tables.iter().map(|t|t.len()).sum();
 for iteration in 0..7 {
  let start=Instant::now();let lz4:Vec<_>=tables.iter().map(|t|lz4_flex::compress_prepend_size(t)).collect();let lz4_ms=start.elapsed().as_secs_f64()*1000.;
  let start=Instant::now();for(t,c)in tables.iter().zip(&lz4){assert_eq!(lz4_flex::decompress_size_prepended(c).unwrap(),*t)}let lz4_decode_ms=start.elapsed().as_secs_f64()*1000.;
  let start=Instant::now();let zstd:Vec<_>=tables.iter().map(|t|zstd::bulk::compress(t,1).unwrap()).collect();let zstd_ms=start.elapsed().as_secs_f64()*1000.;
  let start=Instant::now();for(t,c)in tables.iter().zip(&zstd){assert_eq!(zstd::bulk::decompress(c,t.len()).unwrap(),*t)}let zstd_decode_ms=start.elapsed().as_secs_f64()*1000.;
  println!("{{\"iteration\":{iteration},\"bundle_bytes\":{},\"table_bytes\":{table_bytes},\"full_table_bytes\":{full},\"tables\":{},\"lz4_table_bytes\":{},\"zstd_table_bytes\":{},\"lz4_encode_ms\":{lz4_ms},\"lz4_decode_ms\":{lz4_decode_ms},\"zstd_encode_ms\":{zstd_ms},\"zstd_decode_ms\":{zstd_decode_ms}}}",bytes.len(),tables.len(),lz4.iter().map(|c|c.len()).sum::<usize>(),zstd.iter().map(|c|c.len()).sum::<usize>());
 }
}
